$('naver-inputs').addEventListener('input',ev=>{const el=ev.target;if(el.dataset.field){if(el.readOnly)return;const path=el.dataset.field,type=M.spec[path]?.[1];draft.fields[path]=type==='boolean'?(el.value===''?'':el.value==='true'):el.value;if(path===D+'naverShoppingSearchInfo.brandName'){draft.fields[D+'naverShoppingSearchInfo.brandId']='';$(id(D+'naverShoppingSearchInfo.brandId')).value='';}changed({path:'fields.'+path});}else if(el.dataset.optionName!==undefined){draft.optionNames[Number(el.dataset.optionName)]=el.value;changed();}else if(el.dataset.option!==undefined){const o=draft.options[Number(el.dataset.option)];if(el.dataset.value!==undefined)o.values[Number(el.dataset.value)]=el.value;else o[el.dataset.optionKey]=el.type==='checkbox'?el.checked:el.value;if(['stockQuantity','usable'].includes(el.dataset.optionKey))$(id(P+'stockQuantity')).value=String(draft.options.filter(o=>o.usable!==false).reduce((sum,o)=>sum+(M.integer(o.stockQuantity)?Number(o.stockQuantity):0),0));changed({path:'options',optionId:o.id,key:el.dataset.optionKey||'values'});}else if(el.dataset.cert!==undefined){draft.fields[M.certKey][Number(el.dataset.cert)][el.dataset.certKey]=el.type==='checkbox'?el.checked:el.value;changed();}else if(el.dataset.notice){const n=draft.fields[M.noticeKey],meta=M.notices[n.productInfoProvidedNoticeType];n[meta.branch][el.dataset.notice]=el.value;const check=$('naver-notice-reference');if(check)check.checked=false;changed();}else if(el.dataset.attributeReal){const a=draft.fields[M.attributeKey]?.find(a=>String(a.attributeSeq)===el.dataset.attributeReal);if(a)a.attributeRealValue=el.value;changed();}});
$('naver-inputs').addEventListener('change',ev=>{const el=ev.target;if(keyOf(el)==='naver-option-mode'){if(draft.options.length&&el.value!==draft.optionMode&&!confirm('옵션 유형을 변경하면 작성한 조합형 옵션을 제외합니다. 변경할까요?')){el.value=draft.optionMode;return;}draft.optionMode=el.value;if(el.value==='COMBINATION'&&!draft.optionNames.length)draft.optionNames=['색상'];if(el.value==='COMBINATION'&&!draft.options.length)draft.options.push(M.blankOption(draft.optionNames.length));changed();renderOptions();updateBusy();}else if(keyOf(el)==='naver-notice-type'){const old=draft.fields[M.noticeKey];if(old)noticeBackups.set(old.productInfoProvidedNoticeType,structuredClone(old));if(!M.notices[el.value]){el.value=old?.productInfoProvidedNoticeType||'';error('지원 준비 중인 고시 유형은 아직 선택할 수 없습니다.');return;}draft.fields[M.noticeKey]=noticeBackups.has(el.value)?structuredClone(noticeBackups.get(el.value)):null;if(!draft.fields[M.noticeKey])M.selectNotice(draft,el.value);changed();loadNotice(el.value);}else if(keyOf(el)==='naver-notice-reference'){const n=draft.fields[M.noticeKey],m=M.notices[n.productInfoProvidedNoticeType];if(el.checked){noticeBackups.set('reference-'+n.productInfoProvidedNoticeType,structuredClone(n));for(const f of m.fields)if(typeof n[m.branch][f.name]!=='object')n[m.branch][f.name]=f.type==='text'?'상품 상세페이지 참조':f.type==='reference'?'1':n[m.branch][f.name];}else{const old=noticeBackups.get('reference-'+n.productInfoProvidedNoticeType);if(old)draft.fields[M.noticeKey]=structuredClone(old);}changed();renderNotices();}else if(el.dataset.attributeMulti){const key=el.dataset.attributeMulti,all=draft.fields[M.attributeKey]||[],meta=attributes.find(a=>String(a.attributeSeq)===key),same=all.filter(a=>String(a.attributeSeq)===key);if(el.checked&&same.length>=(meta?.attributeValueMaxMatchingCount||Infinity)){el.checked=false;return error('검색필터 최대 선택 개수를 확인해 주세요.');}draft.fields[M.attributeKey]=all.filter(a=>!(String(a.attributeSeq)===key&&String(a.attributeValueSeq)===el.value));if(el.checked)draft.fields[M.attributeKey].push({attributeSeq:key,attributeValueSeq:el.value});changed();}else if(el.dataset.attributeUnit){const a=draft.fields[M.attributeKey]?.find(a=>String(a.attributeSeq)===el.dataset.attributeUnit);if(a)a.attributeRealValueUnitCode=el.value;changed();}else if(el.dataset.attribute){const key=el.dataset.attribute,all=draft.fields[M.attributeKey]||[],old=all.find(a=>String(a.attributeSeq)===key),list=all.filter(a=>String(a.attributeSeq)!==key);if(el.value)list.push({attributeSeq:key,attributeValueSeq:el.value,...(old?.attributeRealValue?{attributeRealValue:old.attributeRealValue}:{})});draft.fields[M.attributeKey]=list;changed();}else if(el.dataset.field===P+'deliveryInfo.deliveryFee.deliveryFeeType'){const fee=P+'deliveryInfo.deliveryFee.';if(el.value==='FREE')draft.fields[fee+'baseFee']=0;for(const key of ['freeConditionalAmount','repeatQuantity','secondBaseQuantity','secondExtraFee','thirdBaseQuantity','thirdExtraFee'])if(!(el.value==='CONDITIONAL_FREE'&&key==='freeConditionalAmount')&&!(el.value==='UNIT_QUANTITY_PAID'&&key==='repeatQuantity')&&!(el.value==='RANGE_QUANTITY_PAID'&&['secondBaseQuantity','secondExtraFee','thirdBaseQuantity','thirdExtraFee'].includes(key)))draft.fields[fee+key]=null;changed({path:'fields.'+fee+'deliveryFeeType'});renderDelivery();updateBusy();}});
$('naver-inputs').addEventListener('click',async ev=>{const b=ev.target.closest('[data-image-edit],[data-description-edit]');if(!b||b.disabled||busy||imageReading||categoryLoading||!window.ImageCropEditor)return;const owner=draft;let image=b.dataset.imageEdit?draft.images.find(i=>i.id===b.dataset.imageEdit):null;const index=b.hasAttribute('data-description-edit')?Number(b.dataset.descriptionEdit):null,url=image?image.url:ImageCropEditor.htmlImages(draft.description)[index]?.url,assetId=image?image.assetId:url?.match(/^\/api\/marketplaces\/assets\/([a-f0-9-]{36})$/i)?.[1];imageReading=true;updateBusy();try{const result=await ImageCropEditor.open({url,assetId,square:false});if(!result||disposed||draft!==owner)return;if(image){image.assetId=result.assetId;image.url=result.url;}else draft.description=ImageCropEditor.replaceHtml(draft.description,index,result.url);changed({path:image?'images':'description'});renderImages();$('naver-description-input').value=draft.description;updatePreview();}catch(err){error(err.message);}finally{imageReading=false;updateBusy();}});
$('naver-inputs').addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b||busy||categoryLoading||limits.groupProduct)return;const data=b.dataset;if(data.picker)return picker(data.picker,data.addressKind);if(keyOf(b)==='naver-option-add'&&manageOptionRows){draft.options.push(M.blankOption(draft.optionNames.length));changed();renderOptions();updateBusy();}else if(keyOf(b)==='naver-axis-add'&&draft.optionNames.length<3){draft.optionNames.push('옵션 '+(draft.optionNames.length+1));draft.options.forEach(o=>o.values.push(''));changed();renderOptions();updateBusy();}else if(keyOf(b)==='naver-axis-remove'){draft.optionNames.pop();draft.options.forEach(o=>o.values.pop());changed();renderOptions();updateBusy();}else if(data.removeOption!==undefined&&manageOptionRows){draft.options.splice(Number(data.removeOption),1);changed();renderOptions();updateBusy();}else if(keyOf(b)==='naver-certification-add'){const meta=category?.certificationInfos?.find(c=>String(c.id)===$('naver-certification-type').value);if(!meta)return error('카테고리 규격을 조회하고 인증 유형을 선택해 주세요.');const all=draft.fields[M.certKey]||[];if(all.some(c=>String(c.certificationInfoId)===String(meta.id)))return error('이미 추가한 인증 유형입니다.');all.push({certificationInfoId:String(meta.id),certificationKindType:meta.kindTypes?.[0]||'ETC',name:'',certificationNumber:'',companyName:'',certificationMark:false});draft.fields[M.certKey]=all;changed();renderCertifications();updateBusy();}else if(data.certRemove!==undefined){draft.fields[M.certKey].splice(Number(data.certRemove),1);changed();renderCertifications();updateBusy();}else if(data.imageRemove){const index=draft.images.findIndex(i=>i.id===data.imageRemove);if(index>=0){const image=draft.images[index];if(image.local){URL.revokeObjectURL(image.url);localUrls.delete(image.url);}draft.images.splice(index,1);changed();renderImages();}}});
